#include "json.h"
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { JsonDoc *doc; JsonError *error; size_t pos; } Parser;
static void fail(Parser *p,const char *message){if(p->error){p->error->offset=p->pos;snprintf(p->error->message,sizeof p->error->message,"%s",message);}}
static void ws(Parser*p){while(p->pos<p->doc->length&&(p->doc->input[p->pos]==' '||p->doc->input[p->pos]=='\t'||p->doc->input[p->pos]=='\r'||p->doc->input[p->pos]=='\n'))p->pos++;}
static size_t token(Parser*p,JsonType type,size_t start,size_t parent){if(p->doc->count>=JSON_MAX_TOKENS){fail(p,"JSON token limit exceeded");return SIZE_MAX;}size_t i=p->doc->count++;p->doc->tokens[i]=(JsonToken){.type=type,.start=start,.end=start,.next=i+1,.parent=parent};return i;}
static bool hex4(const char*s,size_t n,uint32_t*out){if(n<4)return false;uint32_t x=0;for(size_t i=0;i<4;i++){unsigned char c=(unsigned char)s[i];x<<=4;if(c>='0'&&c<='9')x+=c-'0';else if(c>='a'&&c<='f')x+=c-'a'+10;else if(c>='A'&&c<='F')x+=c-'A'+10;else return false;}*out=x;return true;}
static bool utf8_advance(const char*s,size_t n,size_t*i){unsigned char c=(unsigned char)s[*i];if(c<0x80){(*i)++;return true;}size_t k;uint32_t cp;if(c>=0xC2&&c<=0xDF){k=2;cp=c&0x1F;}else if(c>=0xE0&&c<=0xEF){k=3;cp=c&0x0F;}else if(c>=0xF0&&c<=0xF4){k=4;cp=c&7;}else return false;if(*i+k>n)return false;for(size_t j=1;j<k;j++){unsigned char d=(unsigned char)s[*i+j];if((d&0xC0)!=0x80)return false;cp=(cp<<6)|(d&0x3F);}if((k==3&&cp<0x800)||(k==4&&cp<0x10000)||cp>0x10FFFF||(cp>=0xD800&&cp<=0xDFFF))return false;*i+=k;return true;}
static bool string_scan(Parser*p,size_t parent){size_t start=p->pos++;size_t t=token(p,JT_STRING,start,parent);if(t==SIZE_MAX)return false;while(p->pos<p->doc->length){unsigned char c=(unsigned char)p->doc->input[p->pos];if(c=='"'){p->pos++;p->doc->tokens[t].end=p->pos;p->doc->tokens[t].next=p->doc->count;return true;}if(c<0x20){fail(p,"control byte in JSON string");return false;}if(c=='\\'){p->pos++;if(p->pos>=p->doc->length){fail(p,"truncated escape sequence");return false;}char e=p->doc->input[p->pos++];if(strchr("\"\\/bfnrt",e))continue;if(e!='u'||p->doc->length-p->pos<4){fail(p,"invalid JSON escape");return false;}uint32_t cp;if(!hex4(p->doc->input+p->pos,p->doc->length-p->pos,&cp)){fail(p,"invalid Unicode escape");return false;}p->pos+=4;if(cp>=0xD800&&cp<=0xDBFF){if(p->doc->length-p->pos<6||p->doc->input[p->pos]!='\\'||p->doc->input[p->pos+1]!='u'){fail(p,"unpaired high surrogate");return false;}uint32_t low;if(!hex4(p->doc->input+p->pos+2,p->doc->length-p->pos-2,&low)||low<0xDC00||low>0xDFFF){fail(p,"invalid surrogate pair");return false;}p->pos+=6;}else if(cp>=0xDC00&&cp<=0xDFFF){fail(p,"unpaired low surrogate");return false;}continue;}if(!utf8_advance(p->doc->input,p->doc->length,&p->pos)){fail(p,"invalid UTF-8 in JSON string");return false;}}fail(p,"unterminated JSON string");return false;}
static size_t parse_value(Parser*p,size_t parent,size_t depth);
static size_t parse_container(Parser*p,size_t parent,size_t depth,bool object){size_t start=p->pos++;size_t me=token(p,object?JT_OBJECT:JT_ARRAY,start,parent);if(me==SIZE_MAX)return SIZE_MAX;ws(p);char close=object?'}':']';if(p->pos<p->doc->length&&p->doc->input[p->pos]==close){p->pos++;p->doc->tokens[me].end=p->pos;p->doc->tokens[me].next=p->doc->count;return me;}while(p->pos<p->doc->length){size_t key=SIZE_MAX;if(object){if(p->doc->input[p->pos]!='"'){fail(p,"object key must be a string");return SIZE_MAX;}key=p->doc->count;if(!string_scan(p,me))return SIZE_MAX;ws(p);if(p->pos>=p->doc->length||p->doc->input[p->pos++]!=':'){fail(p,"expected colon after object key");return SIZE_MAX;}for(size_t i=me+1;i<key;){if(p->doc->tokens[i].parent==me){size_t previous=i;char a[256],b[256];if(!json_string_copy(p->doc,previous,a,sizeof a)||!json_string_copy(p->doc,key,b,sizeof b)){fail(p,"object key exceeds supported length");return SIZE_MAX;}if(!strcmp(a,b)){fail(p,"duplicate object key");return SIZE_MAX;}i=p->doc->tokens[previous+1].next;}else i++;}ws(p);}if(parse_value(p,me,depth+1)==SIZE_MAX)return SIZE_MAX;ws(p);if(p->pos>=p->doc->length){fail(p,"unterminated JSON container");return SIZE_MAX;}char c=p->doc->input[p->pos++];if(c==close){p->doc->tokens[me].end=p->pos;p->doc->tokens[me].next=p->doc->count;return me;}if(c!=','){fail(p,"expected comma or container end");return SIZE_MAX;}ws(p);if(p->pos<p->doc->length&&p->doc->input[p->pos]==close){fail(p,"trailing comma in JSON container");return SIZE_MAX;}}
 fail(p,"unterminated JSON container");return SIZE_MAX;}
static size_t parse_value(Parser*p,size_t parent,size_t depth){if(depth>JSON_MAX_DEPTH){fail(p,"JSON nesting limit exceeded");return SIZE_MAX;}ws(p);if(p->pos>=p->doc->length){fail(p,"expected JSON value");return SIZE_MAX;}char c=p->doc->input[p->pos];if(c=='{')return parse_container(p,parent,depth,true);if(c=='[')return parse_container(p,parent,depth,false);if(c=='"'){size_t t=p->doc->count;if(!string_scan(p,parent))return SIZE_MAX;return t;}JsonType type;size_t start=p->pos;if(c=='t'&&p->doc->length-p->pos>=4&&!memcmp(p->doc->input+p->pos,"true",4)){p->pos+=4;type=JT_TRUE;}else if(c=='f'&&p->doc->length-p->pos>=5&&!memcmp(p->doc->input+p->pos,"false",5)){p->pos+=5;type=JT_FALSE;}else if(c=='n'&&p->doc->length-p->pos>=4&&!memcmp(p->doc->input+p->pos,"null",4)){p->pos+=4;type=JT_NULL;}else{if(c=='-')p->pos++;if(p->pos>=p->doc->length||!isdigit((unsigned char)p->doc->input[p->pos])){fail(p,"invalid JSON value");return SIZE_MAX;}if(p->doc->input[p->pos]=='0')p->pos++;else while(p->pos<p->doc->length&&isdigit((unsigned char)p->doc->input[p->pos]))p->pos++;if(p->pos<p->doc->length&&p->doc->input[p->pos]=='.'){p->pos++;if(p->pos>=p->doc->length||!isdigit((unsigned char)p->doc->input[p->pos])){fail(p,"invalid JSON fraction");return SIZE_MAX;}while(p->pos<p->doc->length&&isdigit((unsigned char)p->doc->input[p->pos]))p->pos++;}if(p->pos<p->doc->length&&(p->doc->input[p->pos]=='e'||p->doc->input[p->pos]=='E')){p->pos++;if(p->pos<p->doc->length&&(p->doc->input[p->pos]=='+'||p->doc->input[p->pos]=='-'))p->pos++;if(p->pos>=p->doc->length||!isdigit((unsigned char)p->doc->input[p->pos])){fail(p,"invalid JSON exponent");return SIZE_MAX;}while(p->pos<p->doc->length&&isdigit((unsigned char)p->doc->input[p->pos]))p->pos++;}type=JT_NUMBER;}
 size_t t=token(p,type,start,parent);if(t==SIZE_MAX)return SIZE_MAX;p->doc->tokens[t].end=p->pos;p->doc->tokens[t].next=p->doc->count;return t;}
bool json_parse(JsonDoc*d,const char*input,size_t length,JsonError*error){if(error)memset(error,0,sizeof *error);if(!d||!input||length==0){if(error)snprintf(error->message,sizeof error->message,"empty JSON input");return false;}memset(d,0,sizeof *d);d->input=input;d->length=length;d->tokens=calloc(JSON_MAX_TOKENS,sizeof *d->tokens);if(!d->tokens){if(error)snprintf(error->message,sizeof error->message,"unable to allocate JSON tokens");return false;}Parser p={.doc=d,.error=error};if(parse_value(&p,SIZE_MAX,0)==SIZE_MAX){json_free(d);return false;}ws(&p);if(p.pos!=length){fail(&p,"trailing data after JSON value");json_free(d);return false;}return true;}
void json_free(JsonDoc*d){if(d){free(d->tokens);d->tokens=NULL;d->count=0;}}
static bool emit_cp(uint32_t cp,char*out,size_t cap,size_t*used){unsigned char b[4];size_t n;if(cp<0x80){b[0]=(unsigned char)cp;n=1;}else if(cp<0x800){b[0]=0xC0|(cp>>6);b[1]=0x80|(cp&63);n=2;}else if(cp<0x10000){b[0]=0xE0|(cp>>12);b[1]=0x80|((cp>>6)&63);b[2]=0x80|(cp&63);n=3;}else{b[0]=0xF0|(cp>>18);b[1]=0x80|((cp>>12)&63);b[2]=0x80|((cp>>6)&63);b[3]=0x80|(cp&63);n=4;}if(*used+n>=cap)return false;memcpy(out+*used,b,n);*used+=n;return true;}
bool json_string_copy(const JsonDoc*d,size_t t,char*out,size_t cap){if(!d||t>=d->count||d->tokens[t].type!=JT_STRING||!out||cap==0)return false;size_t i=d->tokens[t].start+1,end=d->tokens[t].end-1,used=0;while(i<end){unsigned char c=(unsigned char)d->input[i++];if(c=='\\'){char e=d->input[i++];if(e=='"'||e=='\\'||e=='/')c=(unsigned char)e;else if(e=='b')c='\b';else if(e=='f')c='\f';else if(e=='n')c='\n';else if(e=='r')c='\r';else if(e=='t')c='\t';else if(e=='u'){uint32_t cp;hex4(d->input+i,end-i,&cp);i+=4;if(cp>=0xD800&&cp<=0xDBFF){uint32_t low;hex4(d->input+i+2,end-i-2,&low);i+=6;cp=0x10000+((cp-0xD800)<<10)+(low-0xDC00);}if(!emit_cp(cp,out,cap,&used))return false;continue;}}if(used+1>=cap)return false;out[used++]=(char)c;}out[used]=0;return true;}
size_t json_object_get(const JsonDoc*d,size_t obj,const char*key){if(!d||obj>=d->count||d->tokens[obj].type!=JT_OBJECT)return SIZE_MAX;for(size_t i=obj+1;i<d->tokens[obj].next;){if(d->tokens[i].parent==obj){char k[256];if(!json_string_copy(d,i,k,sizeof k))return SIZE_MAX;size_t val=i+1;if(!strcmp(k,key))return val;i=d->tokens[val].next;}else i++;}return SIZE_MAX;}
size_t json_array_size(const JsonDoc*d,size_t arr){if(!d||arr>=d->count||d->tokens[arr].type!=JT_ARRAY)return SIZE_MAX;size_t n=0;for(size_t i=arr+1;i<d->tokens[arr].next;){if(d->tokens[i].parent==arr){n++;i=d->tokens[i].next;}else i++;}return n;}
size_t json_array_get(const JsonDoc*d,size_t arr,size_t index){if(!d||arr>=d->count||d->tokens[arr].type!=JT_ARRAY)return SIZE_MAX;size_t n=0;for(size_t i=arr+1;i<d->tokens[arr].next;){if(d->tokens[i].parent==arr){if(n++==index)return i;i=d->tokens[i].next;}else i++;}return SIZE_MAX;}
bool json_integer(const JsonDoc*d,size_t t,int*out){if(!d||t>=d->count||d->tokens[t].type!=JT_NUMBER||!out)return false;size_t i=d->tokens[t].start,end=d->tokens[t].end;if(d->input[i]=='-')return false;long value=0;for(;i<end;i++){char c=d->input[i];if(c<'0'||c>'9')return false;if(value>(2147483647L-(c-'0'))/10)return false;value=value*10+(c-'0');}*out=(int)value;return true;}
bool json_boolean(const JsonDoc*d,size_t t,bool*out){if(!d||t>=d->count||!out)return false;if(d->tokens[t].type==JT_TRUE){*out=true;return true;}if(d->tokens[t].type==JT_FALSE){*out=false;return true;}return false;}
bool json_object_has_only(const JsonDoc*d,size_t obj,const char*const*keys,size_t count){if(!d||obj>=d->count||d->tokens[obj].type!=JT_OBJECT)return false;for(size_t i=obj+1;i<d->tokens[obj].next;){if(d->tokens[i].parent==obj){char key[256];if(!json_string_copy(d,i,key,sizeof key))return false;bool found=false;for(size_t k=0;k<count;k++)if(!strcmp(key,keys[k]))found=true;if(!found)return false;i=d->tokens[i+1].next;}else i++;}return true;}
